Time series: decomposition

dengue &lt;- read_csv("../data/dengue_wards.csv", show_col_types = FALSE) |&gt;
  group_by(year, month) |&gt; summarise(cases = sum(cases), .groups = "drop")
s &lt;- stl(ts(dengue$cases, start = c(2023, 1), frequency = 12), s.window = "periodic")
as_tibble(s$time.series) |&gt; mutate(month = seq(as.Date("2023-01-01"), by = "month", length.out = n()), observed = dengue$cases) |&gt;
  pivot_longer(-month) |&gt; mutate(name = factor(name, c("observed", "trend", "seasonal", "remainder"))) |&gt;
  ggplot(aes(month, value)) + geom_line() + facet_wrap(~ name, ncol = 1, scales = "free_y") +
  labs(x = NULL, y = "Cases", title = "Observed = trend + seasonal + remainder")








stl() separates the seasonal monsoon peak from the slower trend; a large remainder points to an outbreak that the season alone does not explain.

Basic Shiny App Structure
library(shiny)

# UI
ui &lt;- fluidPage(
  titlePanel("Blood Pressure Dashboard"),

  sidebarLayout(
    sidebarPanel(
      selectInput("region", "Region:",
                 choices = c("North", "South", "East", "West")),
      sliderInput("age", "Age Range:",
                 min = 18, max = 80, value = c(18, 80))
    ),

    mainPanel(
      plotOutput("bpPlot"),
      tableOutput("statsTable")
    )
  )
)

# Server
server &lt;- function(input, output) {
  # Reactive data
  filtered_data &lt;- reactive({
    health_data %&gt;%
      filter(Region == input$region,
            Age &gt;= input$age[1], Age &lt;= input$age[2])
  })

  # Outputs
  output$bpPlot &lt;- renderPlot({
    ggplot(filtered_data(), aes(x = Age, y = SysBP_0m)) +
      geom_point() + geom_smooth()
  })

  output$statsTable &lt;- renderTable({
    filtered_data() %&gt;%
      summarise(Mean = mean(SysBP_0m),
               SD = sd(SysBP_0m),
               N = n())
  })
}

shinyApp(ui, server)

Reactive Programming Concepts
Key Reactive Functions:
# reactive() - creates reactive expression
data_filtered &lt;- reactive({
  req(input$region)  # Require input
  health_data %&gt;% filter(Region == input$region)
})

# observe() - side effects (no return value)
observe({
  print(paste("Region changed to:", input$region))
})

# observeEvent() - respond to specific event
observeEvent(input$updateBtn, {
  # Code runs when button clicked
  output$plot &lt;- renderPlot({...})
})

# eventReactive() - reactive value from event
data_on_click &lt;- eventReactive(input$loadBtn, {
  read.csv(input$file$datapath)
})

